import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
// START Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// END Google Fonts Loader



export type BlockedMoneyProps = Record<string, any>;

const BlockedMoney: React.FC<BlockedMoneyProps> = ({
  backgroundColor = "#050505",
  primaryColor = "#FF1744",
  transparentBackground = false,
  durationInSeconds = 5,
  symbolSize = 400,
  strokeWidth = 12,
  glowIntensity = 20,
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Color Parsing
  const bgStyle = transparentBackground ? "transparent" : backgroundColor;
  
  // Layout Calculations
  const radius = symbolSize / 2;
  const centerX = width / 2;
  const centerY = height / 2;
  const circum = 2 * Math.PI * radius;
  
  // Animation Timing - Springs
  const loopEntrance = spring({
    frame: frame - 5,
    fps,
    config: { damping: 200, stiffness: 100, mass: 2 },
  });

  const dollarEntrance = spring({
    frame: frame - 15,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // Derived Animations
  const loopProgress = interpolate(loopEntrance, [0, 1], [0, circum], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const loopOpacity = interpolate(frame, [0, 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Neon Glow Style
  const glowStyle = {
    filter: `drop-shadow(0px 0px ${glowIntensity}px ${primaryColor})`,
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgStyle }}>
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          ...glowStyle,
        }}
      >
        <svg
          width={width}
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          style={{ overflow: "visible" }}
        >
          {/* Circular Loop Path */}
          <circle
            cx={centerX}
            cy={centerY}
            r={radius}
            fill="none"
            stroke={primaryColor}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeDasharray={circum}
            strokeDashoffset={circum - loopProgress}
            opacity={loopOpacity}
            transform={`rotate(-90 ${centerX} ${centerY})`}
            style={{ transition: "none" }}
          />
        </svg>

        {/* Dollar Symbol */}
        <div
          style={{
            position: "absolute",
            fontFamily: "Montserrat",
            fontWeight: 700,
            fontSize: symbolSize * 0.8,
            color: primaryColor,
            transform: `scale(${dollarEntrance})`,
            opacity: dollarEntrance,
          }}
        >
          $
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default BlockedMoney;